export const ASSETS = Object.freeze({
  logoLight: "data:image/png;base64,",
  logoBordo: "data:image/png;base64,",
  patriciaHero: "data:image/webp;base64,",
});

export function hydrateAssets(root = document) {
  root.querySelectorAll("[data-asset]").forEach((image) => {
    const source = ASSETS[image.dataset.asset];
    if (source) image.src = source;
  });
}
